create role anon;
create role authenticated;
create role service_role bypassrls;
create table organizations(id uuid primary key);
create table crm_customers(id uuid primary key default gen_random_uuid(),organization_id uuid,full_name text,email text,phone text,company_name text,status text default 'active' check(status in ('active','inactive','blocked','archived')),metadata jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now(),unique(id,organization_id));
create unique index crm_customers_org_email_unique on crm_customers(organization_id,lower(email)) where email is not null;
create table crm_lead_categories(id uuid primary key,organization_id uuid,name text);
create table crm_customer_category_assignments(organization_id uuid,customer_id uuid,category_id uuid,primary key(organization_id,customer_id,category_id));
create table audit_logs(id uuid default gen_random_uuid(),organization_id uuid,action text,resource_type text,resource_id text,reason text,metadata jsonb default '{}');
create table gencouv_email_messages(id uuid primary key default gen_random_uuid(),organization_id uuid,recipient_email text,recipient_name text,sequence_id uuid,sequence_step_id uuid,lead_id text,read_at timestamptz,replied_from_dashboard_at timestamptz,reply_to_message_id uuid,in_reply_to_header text,references_header text,provider text,provider_email_id text unique,subject text,status text,direction text,from_email text,text_body text,metadata jsonb default '{}',sent_at timestamptz,delivered_at timestamptz,opened_at timestamptz,clicked_at timestamptz,bounced_at timestamptz,complained_at timestamptz,failed_at timestamptz,last_event_at timestamptz,error_message text,stop_reason text,created_at timestamptz default now(),updated_at timestamptz default now());
create table gencouv_email_events(id uuid primary key default gen_random_uuid(),organization_id uuid,email_message_id uuid,provider text,provider_event_id text,provider_email_id text,event_type text,occurred_at timestamptz,payload jsonb,unique(provider,provider_event_id));
create table gencouv_suppression_list(id uuid default gen_random_uuid(),organization_id uuid,normalized_email text,reason text,source text,event_type text,provider_email_id text,payload jsonb,updated_at timestamptz default now(),unique(organization_id,normalized_email));
create table gencouv_campaign_enrollments(id uuid default gen_random_uuid(),organization_id uuid,normalized_email text,campaign_key text,lead_id text,cohort_date date,validation_status text,qualification_status text,current_sequence_step integer,campaign_enrolled_at timestamptz,last_event_at timestamptz,suppression_status text,metadata jsonb,do_not_contact boolean,campaign_status text,stop_reason text,last_delivery_status text,unsubscribe_status text,updated_at timestamptz,constraint gencouv_campaign_enrollments_unique_active unique(organization_id,campaign_key,normalized_email));
create table gencouv_campaign_settings(id uuid primary key default gen_random_uuid(),organization_id uuid,campaign_key text,daily_new_lead_limit integer default 30 check(daily_new_lead_limit between 30 and 200),daily_send_limit integer default 10,sending_enabled boolean default false,status text default 'paused',metadata jsonb default '{}',updated_at timestamptz default now());
create table gencouv_sync_runs(id uuid primary key,organization_id uuid,source text check(source in ('google_sheets','resend','n8n','dashboard')),direction text check(direction in ('inbound','outbound','bidirectional')),status text check(status in ('running','completed','failed','partial')),records_read integer,records_written integer,metadata jsonb default '{}',completed_at timestamptz);

create table gencouv_qualified_leads(id uuid primary key default gen_random_uuid(),organization_id uuid,normalized_email text,email text,first_name text,last_name text,full_name text,product_interest text,broker text,quality_score numeric default 1,created_at timestamptz default now(),qualification_status text default 'qualified',validation_status text default 'valid',do_not_contact boolean default false,suppression_status text,unsubscribe_status text,bounce_status text,campaign_status text,email_sequence_status text,source text,source_id text,raw_lead_id uuid,campaign_enrolled_at timestamptz,last_event_at timestamptz,updated_at timestamptz);

alter table gencouv_qualified_leads add column metadata jsonb default '{}', add column phone text, add column lifecycle_status text, add column last_email_sent_at timestamptz, add column next_follow_up_at timestamptz;
